// Combines all sheet rows into a single text block for the AI.
const rows = $input.all().map(function (item) { return item.json; });

// Sensible limit: the 200 most recent rows (adjust to your sheet).
const trimmed = rows.slice(-200);
const lines = trimmed.map(function (r) { return JSON.stringify(r); }).join('\n');

const system = 'You are an operations analyst writing in English, professional but approachable. ' +
  'Based on the log rows I give you, write the weekly summary for the team: ' +
  '1) what happened this week in 3-4 sentences; ' +
  '2) the key figures that can be derived from the rows (totals, breakdowns), citing which column they come from; ' +
  '3) points to watch: at most 3, only if the data supports them; ' +
  '4) what to keep an eye on next week. ' +
  'Never invent data not present in the rows. If something cannot be known from this data, say so. ' +
  'Format: plain email text, no markdown, maximum 300 words.';

const payload = {
  model: 'claude-sonnet-5',
  max_tokens: 1200,
  system: system,
  messages: [ { role: 'user', content: 'Log rows (one per line, as JSON):\n' + lines } ]
};

return [ { json: { payload: payload, totalRows: rows.length } } ];

// Collects the drafted text and the number of rows analyzed.
const raw = ($json.content && $json.content[0] && $json.content[0].text) ? $json.content[0].text : 'The AI did not return text. Check the execution in n8n.';
const total = $('Condense rows').first().json.totalRows;

return [ { json: { summary: raw.trim(), totalRows: total } } ];
